import asyncio
from aiohttp import web
from aiohttp.test_utils import TestClient, TestServer

@web.middleware
async def errors_as_json(request, handler):
    try:
        return await handler(request)
    except web.HTTPException as e:
        return web.json_response({"error": e.reason}, status=e.status)
@web.middleware
async def auth(request, handler):
    if request.headers.get("Authorization") != "Bearer secret":
        raise web.HTTPUnauthorized()
    request["user"] = "ada"                   # pass data to handlers
    return await handler(request)
async def me(request):
    return web.json_response({"user": request["user"]})
async def demo():
    app = web.Application(middlewares=[errors_as_json, auth])
    app.router.add_get("/me", me)
    async with TestClient(TestServer(app)) as c:
        for h in ({}, {"Authorization": "Bearer secret"}):
            print(await (await c.get("/me", headers=h)).json())  # {'error': 'Unauthorized'}, then {'user': 'ada'}
asyncio.run(demo())
